// Parseamos el JSON que devuelve Claude en content[0].text
const claudeResponse = $input.first().json.content[0].text;

let parsed;
try {
  parsed = JSON.parse(claudeResponse);
} catch (error) {
  // Si Claude devuelve algo que no es JSON válido, lo marcamos como Manual Review
  parsed = {
    categoria: "Manual Review",
    confidence: 0,
    categoria_secundaria: "Manual Review",
    razon: "Error al parsear respuesta del modelo: " + error.message,
    parse_error: true
  };
}

// Devolvemos un objeto plano con los campos clasificados
return [
  {
    json: {
      categoria: parsed.categoria,
      confidence: parsed.confidence,
      categoria_secundaria: parsed.categoria_secundaria,
      razon: parsed.razon,
      needs_review: parsed.confidence < 60 || parsed.parse_error === true || parsed.categoria === "Manual Review",
      parse_error: parsed.parse_error || false,
      nivel_interes: parsed.nivel_interes || 'n/a'
    }
  }
];

